def sha(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for c in iter(lambda: f.read(65536), b""):
            h.update(c)
    return h.hexdigest()


changed = {
    "src/human_fall_detection/core/ground.py": os.path.join(pkg, "core", "ground.py"),
    "src/human_fall_detection/scripts/calibrate_sensors.py": os.path.join(pkg, "scripts", "calibrate_sensors.py"),
    "src/human_fall_detection/config/geometry_constrained.yaml": os.path.join(pkg, "config", "geometry_constrained.yaml"),
    "src/human_fall_detection/tests/test_gl01_constrained_ground.py": os.path.join(pkg, "tests", "test_gl01_constrained_ground.py"),
