    "src/human_fall_detection/config/geometry.yaml": (os.path.join(pkg, "config", "geometry.yaml"), "be485148"),
    "src/human_fall_detection/config/default.yaml": (os.path.join(pkg, "config", "default.yaml"), "221d9dad"),
    "src/human_fall_detection/core/calibration.py": (os.path.join(pkg, "core", "calibration.py"), "5a8f066c"),
    "src/human_fall_detection/tests/test_hf03_geometry.py": (os.path.join(pkg, "tests", "test_hf03_geometry.py"), "5600c139"),
}
out = {"changed": {k: sha(v) for k, v in changed.items()}, "frozen": {}}
for name, (path, prefix) in frozen.items():
    digest = sha(path)
    out["frozen"][name] = {"sha256": digest, "expected_prefix": prefix,
                           "unchanged": digest.startswith(prefix)}
r3 = os.path.join(root, "docs", "human_fall", "evidence", "2026-10-01_gl01_r3")
with open(os.path.join(r3, "00_source_hashes.json"), "w", encoding="utf-8") as f:
    json.dump(out, f, indent=2)
with open(os.path.join(r3, "22_changed_hashes.txt"), "w", encoding="utf-8") as f:
